import java.util.Scanner;
​
public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt(); // 读取 n
        int m = scanner.nextInt(); // 读取 m
        scanner.close(); // 关闭输入流
​
        int cols = (n + m - 1) / m; // 计算列数，向上取整
        int[][] matrix = new int[m][cols]; // 定义矩阵
        // 初始值
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < cols; j++) {
                matrix[i][j] = -1;
            }
        }
​
        int num = 1, top = 0, bottom = m - 1, left = 0, right = cols - 1;
​
        while (num <= n) {
            for (int i = left; i <= right && num <= n; i++) matrix[top][i] = num++; // 从左到右
            top++;
            for (int i = top; i <= bottom && num <= n; i++) matrix[i][right] = num++; // 从上到下
            right--;
            for (int i = right; i >= left && num <= n; i--) matrix[bottom][i] = num++; // 从右到左
            bottom--;
            for (int i = bottom; i >= top && num <= n; i--) matrix[i][left] = num++; // 从下到上
            left++;
        }


        // 输出矩阵
        StringBuilder output = new StringBuilder();
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < cols; j++) {
                output.append(matrix[i][j] == -1 ? "*" : matrix[i][j]);
                if (j < cols - 1) output.append(" "); // 避免最后一列后多余空格
            }
            output.append("\n");
        }
        System.out.print(output); // 一次性输出，提高性能
    }
}
