const readline = require("readline");
​
const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});
​
rl.on("line", (input) => {
    const [n, m] = input.split(" ").map(Number);
    const cols = Math.ceil(n / m); // 计算列数，向上取整
    let matrix = Array.from({ length: m }, () => Array(cols).fill(0)); // 定义矩阵
​
    let num = 1, top = 0, bottom = m - 1, left = 0, right = cols - 1;
​
    while (num <= n) {
        for (let i = left; i <= right && num <= n; i++) matrix[top][i] = num++; // 从左到右
        top++;
        for (let i = top; i <= bottom && num <= n; i++) matrix[i][right] = num++; // 从上到下
        right--;
        for (let i = right; i >= left && num <= n; i--) matrix[bottom][i] = num++; // 从右到左
        bottom--;
        for (let i = bottom; i >= top && num <= n; i--) matrix[i][left] = num++; // 从下到上
        left++;
    }
​
    let output = matrix.map(row => row.map(cell => cell === 0 ? '*' : cell).join(" ")).join("\n");
    console.log(output);
​
    rl.close();
});
