package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "strings"
)
​
func main() {
    // 读取输入
    reader := bufio.NewReader(os.Stdin)
    line, _ := reader.ReadString('\n')
    fields := strings.Fields(line)
    n, _ := strconv.Atoi(fields[0])
    m, _ := strconv.Atoi(fields[1])
​
    cols := (n + m - 1) / m // 计算列数，向上取整
    matrix := make([][]int, m)
    for i := range matrix {
        matrix[i] = make([]int, cols)
    }
​
    num, top, bottom, left, right := 1, 0, m-1, 0, cols-1
​
    for num <= n {
        // 右移
        for i := left; i <= right && num <= n; i++ {
            matrix[top][i] = num
            num++
        }
        top++
        // 下移
        for i := top; i <= bottom && num <= n; i++ {
            matrix[i][right] = num
            num++
        }
        // 左移
        right--
        for i := right; i >= left && num <= n; i-- {
            matrix[bottom][i] = num
            num++
        }
        bottom--
        // 上移
        for i := bottom; i >= top && num <= n; i-- {
            matrix[i][left] = num
            num++
        }
        left++
    }
​
    // 输出矩阵
    var output strings.Builder
    for i := 0; i < m; i++ {
        for j := 0; j < cols; j++ {
            if matrix[i][j] == 0 {
                output.WriteString("*")
            } else {
                output.WriteString(strconv.Itoa(matrix[i][j]))
            }
            if j < cols-1 {
                output.WriteString(" ") // 避免末尾空格
            }
        }
        output.WriteString("\n")
    }
    fmt.Print(output.String()) // 一次性输出，提高性能
}
